{
  "start": "-PT6H",
  "widgets": [
    {
      "type": "text",
      "width": 24,
      "height": 3,
      "properties": {
        "markdown": "# Rayito\nLogs de los sandboxes (Logs Insights sobre `/rayito/*`). Cada widget de log ejecuta su consulta al abrir o refrescar el dashboard y CloudWatch factura los datos escaneados: usa un intervalo corto."
      }
    },
    {
      "type": "log",
      "width": 12,
      "height": 6,
      "properties": {
        "region": "us-east-1",
        "title": "Líneas de log por intervalo",
        "query": "SOURCE logGroups(namePrefix: ['/rayito/']) | stats count(*) as lines by bin(5m)",
        "view": "timeSeries"
      }
    },
    {
      "type": "log",
      "width": 12,
      "height": 6,
      "properties": {
        "region": "us-east-1",
        "title": "Errores por intervalo",
        "query": "SOURCE logGroups(namePrefix: ['/rayito/']) | filter @message like /(?i)error|exception|traceback|fatal|panic/\n| stats count(*) as errors by bin(5m)",
        "view": "timeSeries"
      }
    },
    {
      "type": "log",
      "width": 12,
      "height": 6,
      "properties": {
        "region": "us-east-1",
        "title": "Líneas por grupo de logs",
        "query": "SOURCE logGroups(namePrefix: ['/rayito/']) | stats count(*) as lines by @log\n| sort lines desc\n| limit 20",
        "view": "table"
      }
    },
    {
      "type": "log",
      "width": 12,
      "height": 6,
      "properties": {
        "region": "us-east-1",
        "title": "Streams más ruidosos",
        "query": "SOURCE logGroups(namePrefix: ['/rayito/']) | stats count(*) as lines by @logStream\n| sort lines desc\n| limit 20",
        "view": "table"
      }
    },
    {
      "type": "log",
      "width": 24,
      "height": 6,
      "properties": {
        "region": "us-east-1",
        "title": "Errores recientes",
        "query": "SOURCE logGroups(namePrefix: ['/rayito/']) | filter @message like /(?i)error|exception|traceback|fatal|panic/\n| fields @timestamp, @logStream, @message\n| sort @timestamp desc\n| limit 50",
        "view": "table"
      }
    }
  ]
}

